import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Generative World Renderer at the Speed of Play","description":"","frontmatter":{"title":"Generative World Renderer at the Speed of Play","arxiv":"2607.18703","date":"2026-07-21","authors":"Guixu Lin, Zheng-Hui Huang, Siqi Yang, Ming-Hsuan Yang, Kaipeng Zhang, Zhixiang Wang","categories":"cs.CV","topics":"世界模型, 实时生成渲染, 少步蒸馏","outline":[2,2]},"headers":[],"relativePath":"papers/2607.18703.md","filePath":"papers/2607.18703.md","lastUpdated":null}'),e={name:"papers/2607.18703.md"};function l(r,s,i,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="generative-world-renderer-at-the-speed-of-play" tabindex="-1">Generative World Renderer at the Speed of Play <a class="header-anchor" href="#generative-world-renderer-at-the-speed-of-play" aria-label="Permalink to &quot;Generative World Renderer at the Speed of Play&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.18703" target="_blank" rel="noreferrer">2607.18703</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-21</td></tr><tr><td><strong>作者</strong></td><td>Guixu Lin, Zheng-Hui Huang, Siqi Yang, Ming-Hsuan Yang, Kaipeng Zhang, Zhixiang Wang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>让物理引擎继续负责世界演化、只把着色交给生成模型，通过自回归流式化、四步蒸馏与轻量 codec 把 G-buffer 渲染器从 0.56 FPS 推到 31.54 FPS，做出一个 30 FPS 可玩、可用文本实时换风格的生成式世界。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>生成模型给交互式视觉世界提供了一条路，但只从文本 prompt 或控制提示合成帧的方法，在世界演化过程中往往保不住场景结构、材质属性和玩法逻辑。一个更有原则的替代方案是分工：让物理引擎继续负责模拟世界，只把<strong>外观生成</strong>交给生成式渲染器。</p><p>现代游戏引擎恰好已经暴露了这个接口。延迟渲染里，场景先被光栅化成物理与几何缓冲——深度、法线、albedo、粗糙度、金属度——之后才被着色成 RGB 帧。这些 G-buffer 编码了结构化的世界状态，同时把最终外观留空。因为几何、物理和玩法逻辑仍在引擎手里，&quot;引擎 + 生成渲染器&quot;这个范式<strong>由构造</strong>保住了演化中的世界。</p><p>AlayaRenderer 是这个方向上的代表工作，在视觉复杂的 AAA 游戏语料上训练，能渲染远超以往 G-buffer 渲染器的场景复杂度，并支持文本引导的外观控制——玩家可以改光照、氛围、艺术风格，而不动几何、材质与玩法。但它是离线渲染器：50 步去噪主导推理成本，G-buffer 编码与 VAE 解码还各是一个瓶颈；更根本的是它的双向定窗构造无法在活的游戏引擎产生的无界 G-buffer 流上做自回归 rollout。结果是可 prompt 控制的渲染跑不到交互帧率。</p><p>这个 gap 值得填，因为它决定了生成式世界渲染是&quot;离线后处理管线&quot;还是&quot;能跟着游玩跑的东西&quot;。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>G-buffer 条件的生成渲染</strong>：RGB↔X、FrameDiffuser、RenderFlow、DiffusionRenderer 这一族已经证明，条件于 G-buffer 的生成模型可以替代传统着色阶段并忠实遵守底层场景结构。论文在实验里对它们做了能力矩阵式的对比，缺陷定位得很具体：RGB↔X 做独立逐帧渲染、没有时序建模，因而在评测方法里内容相似度最低、FVD 最高，尽管它支持文本引导的外观控制；FrameDiffuser 引入自回归时序建模，内容相似度优于 RGB↔X，但<strong>不支持 prompt 控制的渲染</strong>，且时序稳定性明显更弱，推理只有 0.31 FPS；DiffusionRenderer 是双向构造，评测时必须把 150 帧序列切成多个独立的 25 帧窗口离线渲染，这个协议反而让它能利用窗口内的未来上下文（对双向方法有利），即便如此也只有 1.10 FPS。</p><p><strong>教师模型 AlayaRenderer</strong> 的三个具体瓶颈：50 步去噪、五路独立的 Wan VAE G-buffer 编码、以及流式 Wan VAE 解码；加上双向定窗（21 latent 帧的 chunk）无法自回归。</p><p><strong>加速侧可借的工具</strong>：CFG 蒸馏、Progressive Distillation、Self Forcing 的 self-rollout 训练、DMD 式对抗分布匹配、Mean Flow Distillation、TAEHV 这类轻量 VAE。论文的贡献不在于发明其中任何一个，而在于把它们按正确顺序组合起来并诚实报告哪一步失败了。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是接受分工前提：引擎管世界，模型管外观。这不是本文提出的，是 AlayaRenderer 已经确立的路线。</p><p>第二步是看清&quot;离线到实时&quot;不是一个瓶颈而是三个：去噪步数、编解码、以及<strong>构造上的不可流式</strong>。前两个是速度问题，第三个是能力问题——就算把 50 步压到 1 步，双向定窗仍然吃不下无界流。所以顺序上必须先解决自回归化，再谈加速。</p><p>第三步是自回归化带来的新问题：历史怎么带。全保留则注意力成本爆炸，全丢则外观漂移。折中是按时间距离分级压缩，近处保真、远处逐级粗化。但这还不够——长 rollout 里最容易丢的是<strong>全局外观基调</strong>，所以额外把第一个生成的 latent 帧作为全局外观锚点，永久挂在最高保真层，让每个 chunk 都能注意到流的初始外观。</p><p>第四步是 prompt 控制在长 rollout 下的保持。cross-attention 的条件在很长的自回归序列里会被历史稀释，于是作者在每个 self-attention 层加一组从风格 prompt 投影出的持久 KV 条目（text sink），让每个 chunk 除了标准 cross-attention 之外还能通过 self-attention 持续注意 prompt。</p><p>第五步是蒸馏的稳定性。直接把 50 步压到 4 步会崩，因为每一步要近似的轨迹比教师训练时长得多。作者的判断是最后的分布精化阶段对初始化<strong>高度敏感</strong>，因此需要前两阶段先把学生温和地带到 4 步预算附近。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>要把生成渲染器塞进游玩循环，光减去噪步数不够——双向定窗在构造上就吃不下引擎吐出的无界流。先把渲染改成自回归的分块流式，历史按时间距离分级压缩并钉一个全局外观锚点；然后再把 50 步渐进蒸成 4 步；最后把两端的 VAE 换成蒸馏过的轻量版本。三件事各解决一个瓶颈，缺一个都到不了播放帧率。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以在 SuperTuxKart 里一边开车一边把画面切成&quot;赛博朋克&quot;为例。</p><p><strong>1. G-buffer 条件的 latent 渲染</strong>。底座是 Wan 2.1 潜视频扩散模型，去噪 Wan causal 3D VAE 产生的 RGB video latent，并通过 cross-attention 条件于文本。引擎提供五路同步物理缓冲——albedo、depth、metallic、normal、roughness——描述几何与材质而非最终外观。每个 G-buffer 通道被当作视频流用同一个 Wan causal 3D VAE 编码，得到帧对齐的 latent，沿通道维拼成条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，在第一个 3D patch embedding 之前与含噪 RGB latent 拼接：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">PatchEmbed</span></span><span class="mopen">([</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">])</span></span></span></span></span></p><p>这个条件方式只需要把第一个 patch embedding 的输入投影加宽以容纳额外条件通道，diffusion transformer 的其余部分完全不动。</p><p><strong>2. 自回归流式</strong>。把 latent 视频切成定长 chunk，实验中每 chunk 含 4 个 latent 帧，已生成的 chunk 保留作为后续生成的历史。历史组织成<strong>三级压缩层次</strong>，压缩程度由与当前 chunk 的时间距离决定：近处历史全保真，远处逐级压成更粗的表示。第一个生成的 latent 帧额外作为<strong>全局外观锚点</strong>，被前置到最高保真层。去噪时所有保留的历史作为 clean latent token 一起进 self-attention，G-buffer latent 仍是逐 chunk 的几何与材质条件。为在任意长的 rollout 上保住 prompt 可控性，每个 self-attention 层再加一组从风格 prompt 嵌入投影出的持久 KV（text sink）。编解码同样做成因果的：VAE encoder 跨 chunk 携带时间特征 cache，使 G-buffer 流被当作一条连续序列编码；decoder 的时间状态跨 chunk 调用持久化，使逐 chunk 流式解码在数值上与整条 latent 流的单次解码一致。</p><p><strong>3. 少步蒸馏（三阶段）</strong>。<strong>Guidance Distillation</strong>：自回归渲染器仍依赖 CFG，每个去噪步要两次网络前向；把教师在目标 guidance scale 下的 CFG 合成速度场蒸馏进学生，此阶段学生保留 50 步调度，只学会用一次前向复现教师的 guided 预测，把显式 CFG 转成权重里的行为。<strong>Progressive Step Reduction</strong>：直接在 4 步预算下训会不稳，于是依次用 32、16、8、最后 4 步调度训练，让学生逐步适应越来越大的去噪间隔。<strong>Mean Flow Distillation under self-rollout</strong>：4 步学生在 Self Forcing 的 self-rollout 训练下精化，只条件于自己之前生成的 chunk 而非真值 RGB 历史，匹配部署设定、缩小 teacher-forcing 训练与自回归推理之间的差距。作者诚实报告了一次失败：他们试过 DMD 式对抗分布匹配，但在本设定下优化不稳、出现明显色偏，因此改用 MFD，其基于 flow 的匹配目标在 4 步精化下稳定得多且视觉保真度相当。最后，激进的步数削减不可避免地压制高频细节，于是在中间 transformer 特征与最终 latent 预测上挂轻量 GAN head（MFD+GAN），对抗损失权重很小，用来找回局部纹理而不干扰 MFD 目标。</p><p><strong>4. 蒸馏轻量 codec</strong>。去噪压到几步之后，剩余延迟被两端的 VAE 主导：编码需要五次独立 Wan VAE 前向（每个 G-buffer 通道一次），解码依赖流式 Wan VAE decoder。Tiny decoder 采用 TAEHV 架构并从其公开的 Wan 2.1 预训练权重初始化，但这些权重对游戏域内容重建不够好，于是从冻结的 Wan VAE decoder 再蒸馏一次：两个 decoder 吃同样的 latent，tiny decoder 用像素重建损失加小权重感知损失去复现 Wan VAE decoder 的输出。Tiny G-buffer encoder 同理，用一次前向预测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 取代五次独立编码，先蒸馏对齐冻结 Wan VAE encoder 的 latent，再与整个渲染器联合微调。</p><p><strong>5. 实时部署</strong>。推理时 G-buffer 流被 tiny encoder 连续编码、由四步扩散模型渲染、再由有状态的 tiny decoder 解成 RGB 帧，所有组件自回归运行并跨 chunk 边界维持持久时间状态，因而可以在无界输入流上连续渲染而不必重启管线。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文是技术报告，形式化很少，只有条件拼接一式：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">PatchEmbed</span></span><span class="mopen">([</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">])</span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是 chunk <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 的含噪 RGB latent、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是对应的 G-buffer 条件。这个式子的意义在于<strong>最小改动</strong>：把条件从 cross-attention 挪到输入通道拼接，只需加宽第一层投影，DiT 主体保持不变，因而可以直接继承 Wan 2.1 的预训练权重。</p><p>评测侧有一个自定义指标值得展开——prompt 可控性用对比式 CLIP margin 量化：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0713em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">CLIP</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8213em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">+</span></span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0713em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">CLIP</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8213em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span></span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9658em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7713em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">+</span></span></span></span></span></span></span></span></span></span></span></span> 是用于生成的条件 prompt，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9658em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7713em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span></span></span></span></span></span></span></span></span></span></span></span> 是来自另一段测试片段的对比 prompt（prompt 切换评测中则取前一个 prompt）。取差值而非绝对相似度，是为了抵消 CLIP 对不同 prompt 的固有偏置——绝对相似度高可能只是因为那句 prompt 恰好落在 CLIP 空间的高密度区域，差值才反映文本对渲染外观（光照、颜色、天气、氛围）的真实控制力。不做文本条件的方法在这一列标为不适用。</p><p>其余指标：内容保持用 OpenCLIP ViT-L/14 的图像—图像相似度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span><span class="mord text mtight"><span class="mord mtight">-</span></span><span class="mord mathrm mtight">I</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（对光照、颜色、风格变化相对不敏感，因而适合评&quot;结构保住了没&quot;）；时序稳定用 warped temporal LPIPS，先用稠密光流把前一帧对齐到当前帧再算 LPIPS，越低越少感知闪烁；跨窗一致性用相邻评测窗口的 Boundary MSE 与 Boundary SSIM。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>数据与设置</strong>：引擎采集的《黑神话：悟空》数据集，1280×720、30 FPS，1,352 段训练片段与 131 段测试片段，每帧含 RGB 参考与五路对齐 G-buffer。除非另说，量化结果都在 131 段测试片段上报告，每段 150 帧（5 秒），模型输入分辨率 832×448。全部训练在 8 张 NVIDIA H200 上完成。</p><p><strong>三个改动各贡献多少？</strong> 作者做了一条受控的渐进链，四个配置在同样的 5 秒协议、同样的 G-buffer 输入与 prompt 下评测。</p><ul><li><strong>自回归重构</strong>（AlayaRenderer-AR，仍 50 步）：内容相似度 0.836→0.846，Boundary MSE 0.0500→0.0433，Boundary SSIM 0.308→0.358；时序稳定性<strong>下降</strong>（tLPIPS 0.124→0.197），反映自回归设定本身更难；吞吐 0.56→1.53 FPS，远未达播放帧率——说明只做流式化不足以实时。</li><li><strong>4 步蒸馏</strong>：吞吐 1.53→6.30 FPS 且峰值显存不变；内容相似度、边界一致性、prompt 可控性与 50 步版持平或略好；时序稳定性反而<strong>明显改善</strong>，tLPIPS 从 0.197 降到 0.158。</li><li><strong>轻量部署</strong>（换成蒸馏 codec，扩散主体不变）：吞吐 6.30→31.54 FPS，峰值显存 22.6 GB→16.2 GB，渲染质量在内容相似度与边界一致性上保持或略升（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span><span class="mord text mtight"><span class="mord mtight">-</span></span><span class="mord mathrm mtight">I</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 0.847、Boundary MSE 0.0406、Boundary SSIM 0.430）。作者把质量不降反升归因于轻量编解码器是在目标游戏域上蒸馏并微调过的。</li></ul><p><strong>与外部基线比？</strong> 同一 5 秒协议下，RGB↔X 内容相似度 0.820、FVD 1031.3、tLPIPS 0.305、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 0.027、1.30 FPS；FrameDiffuser 0.844、FVD 650.6、tLPIPS 0.440、无 prompt 控制、0.31 FPS；AlayaRenderer-Flash 0.847、FVD 384.1、tLPIPS 0.155、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 0.043、31.54 FPS。作者还重训了 DiffusionRenderer，并诚实地给了它有利的协议（双向，150 帧切成多个独立 25 帧窗口离线渲染，可用窗口内未来上下文）：它拿到更高的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span><span class="mord text mtight"><span class="mord mtight">-</span></span><span class="mord mathrm mtight">I</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 0.870 与更低的 FVD 335.5，时序稳定性相当（tLPIPS 0.156），但只有 1.10 FPS。结论表述得很克制：双向方法在有利协议下能拿到更强的离线渲染质量，但 AlayaRenderer-Flash 是<strong>唯一</strong>同时支持因果流式、prompt 切换、少步推理与实时交互渲染的方法。</p><p><strong>长 rollout 下 prompt 还能切吗？</strong> 在 637 帧的单次流式 pass 中，每 5 个 chunk 切一次 prompt，循环 8 种涵盖艺术风格、光照条件、天气效果与配色的提示。作者报告模型持续跟随每次 prompt 转换，同时保住场景几何、角色运动与相机轨迹，转换平滑无明显 ghosting 或边界伪影。</p><p><strong>能真的玩吗？</strong> 把模型适配到开源游戏 SuperTuxKart：先采目标域数据（同步 RGB 与同样五路 G-buffer）微调，再集成进活的引擎。玩家用标准输入控制车辆与视角，同时用预设风格或任意文本独立指定外观；引擎持续更新世界状态并导出同步 G-buffer 流。单张 H200 上，渲染器本身（G-buffer 编码 + 四步扩散 + RGB 解码）跑 31.54 FPS；算上引擎侧 G-buffer 回读、数据传输与显示同步，完整交互系统在实机游玩中稳定维持 30 FPS 的目标播放帧率。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：把世界演化留给物理引擎、只让生成模型做着色，是保住场景结构与玩法逻辑的一条有原则的路，但教师模型 AlayaRenderer 的 50 步去噪、五路 VAE 编码与双向定窗构造让它只能离线跑。AlayaRenderer-Flash 用三件事补齐：chunk 级自回归流式（历史按时间距离三级压缩，首个 latent 帧作全局外观锚点，每层 self-attention 加 text sink 保住长 rollout 的 prompt 控制），三阶段少步蒸馏（guidance 蒸馏 → 32/16/8/4 渐进降步 → self-rollout 下的 Mean Flow Distillation 加轻量 GAN head），以及蒸馏出的 tiny G-buffer encoder 与 tiny decoder。吞吐从 0.56 FPS 依次经 1.53、6.30 到 31.54 FPS，显存从 22.6 GB 降到 16.2 GB，而内容相似度、边界一致性、prompt 可控性保持或略升。相对外部基线，它在 FVD（384.1）与时序稳定性（0.155）上优于 RGB↔X 与 FrameDiffuser，并且是唯一同时具备因果流式、prompt 切换、少步推理与实时能力的方法。接进 SuperTuxKart 后完整交互系统稳定在 30 FPS，玩家可在游玩中随时用文本换风格而不影响引擎侧逻辑。</p><p><strong>3 句话版</strong>：生成式世界渲染要进游玩循环，卡在三个独立瓶颈上：去噪步数、编解码开销、以及双向定窗吃不下无界流。AlayaRenderer-Flash 分别用四步蒸馏、蒸馏轻量 codec 和自回归分块流式解决，把 0.56 FPS 推到 31.54 FPS 而质量基本不掉。代价是相对有利协议下的双向方法仍有一小截离线质量差距。</p><p><strong>1 句话版</strong>：把着色交给生成模型、把世界交给引擎，实时的关键不是更快的扩散而是能吃无界流的构造。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>G-buffer 足以完全刻画渲染所需的世界状态，因而生成器可以只做&quot;着色&quot;这一步</strong>。整个范式的安全性论证——&quot;几何、物理和玩法逻辑仍在引擎手里，所以演化中的世界由构造被保住&quot;——完全建立在这一点上。如果 G-buffer 不足，那么生成器就必须自己发明缺失的信息，而它发明的部分不受引擎约束，&quot;由构造保住&quot;这个论证就失效了。</p><p>它在实践中可能不成立的原因很具体。五路缓冲（albedo、depth、normal、roughness、metallic）描述的是<strong>当前可见表面的属性</strong>，它们编码不了几类对最终画面影响很大的量：光源的位置、数量与强度（延迟渲染里这是着色阶段的输入，不在 G-buffer 里），透明与半透明物体（深度缓冲对它们本就有歧义），体积效果如雾、烟、体积光，以及屏幕外的间接光照来源。这些恰好是&quot;换风格&quot;最容易触及的维度——把场景改成&quot;火山&quot;意味着改光源，而光源不在条件里，模型只能猜。一旦猜，它猜出来的光照就与引擎侧的世界状态无关，跨帧一致性只能靠自回归历史维持，而历史是被三级压缩过的。</p><p>论文为它提供的证据是真实的：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span><span class="mord text mtight"><span class="mord mtight">-</span></span><span class="mord mathrm mtight">I</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 达到 0.847，定性上作者报告模型在整段 rollout 中保持稳定的光照、场景几何与相机运动，且 637 帧 8 次 prompt 切换下几何、角色运动与相机轨迹都被保住。缺的证据是<strong>结构保真的直接度量</strong>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span><span class="mord text mtight"><span class="mord mtight">-</span></span><span class="mord mathrm mtight">I</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是语义层的图像相似度，作者自己说它对光照、颜色、风格变化相对不敏感——这正是它被选中的理由，但也意味着它测不出几何漂移。没有报告生成帧与 G-buffer 深度/法线的重投影一致性误差，而这才是&quot;结构没被改动&quot;的直接证据。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不复现 8 卡蒸馏，只测 §9 的结构保真。</p><ul><li><strong>数据</strong>：从论文的 131 段测试片段中取 30 段，或用 SuperTuxKart 自采一小批同构数据（RGB + 五路 G-buffer + 相机内外参）。优先选含透明物体、明显光源变化、体积雾的片段。</li><li><strong>实现</strong>：不训练模型。若权重可得直接用；否则用任一开源 G-buffer 条件渲染器做替代被试。关键是实现<strong>几何一致性度量</strong>：用真值深度与相机位姿把第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 帧的生成结果重投影到第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6984em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 帧，与第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6984em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 帧的生成结果比对，在几何有效（非遮挡、非视野外）的像素上算 L1 与 LPIPS。</li><li><strong>测量</strong>：三条曲线随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 的变化——(a) 重投影误差；(b) 生成帧经单目深度估计后与真值 G-buffer 深度的 AbsRel；(c) 同样两条曲线但只在标注为&quot;含透明/体积效果&quot;的区域上统计。再加一组 prompt 切换前后的对比：切换到改变光照的 prompt（火山、深海）后，(a) 与 (b) 是否跳变。</li><li><strong>判据</strong>：若重投影误差与深度 AbsRel 在整段 rollout 上保持平稳，且 prompt 切换不引起跳变，则&quot;G-buffer 足以约束结构&quot;得到支持。若误差在透明/体积区域显著更高，或改光照的 prompt 引起深度一致性明显劣化，则说明生成器在 G-buffer 未覆盖的维度上确实在自由发挥，范式的安全性论证需要补充条件通道（例如把光源参数也导出为条件）。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击是给&quot;质量基本没掉&quot;这个结论一个替代解释：<strong>评测协议系统性地偏袒了本方法</strong>。</p><p>论据有三条，都能从论文自己的表格里读出来。其一，时序稳定性这一列的走向很反直觉：教师 AlayaRenderer 的 tLPIPS 是 0.124，是全表最好的；自回归化后劣化到 0.197，4 步蒸馏改善到 0.158，最终版 0.155——<strong>始终没有回到教师水平</strong>。作者把 0.124 归因于&quot;双向定窗更容易平滑&quot;，但这也可以反过来读：本方法在最直接的闪烁度量上相对教师是净损失，而摘要用&quot;保留了教师的核心渲染能力&quot;来概括。其二，DiffusionRenderer 在被作者称为&quot;对双向方法有利&quot;的协议下，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span><span class="mord text mtight"><span class="mord mtight">-</span></span><span class="mord mathrm mtight">I</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 0.870 与 FVD 335.5 都优于本方法的 0.847 与 384.1，时序稳定性还相当（0.156 vs 0.155）——也就是说在质量维度上本方法并不领先，领先的只有速度。这是一个合理的工程取舍，但需要被明确说成取舍。其三，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 这一列：教师 0.039，4 步蒸馏版 0.045，最终版 0.043，自回归 50 步版反而只有 0.030。prompt 可控性在这几个数之间的波动幅度与它们彼此的差距同量级，很难说 text sink 带来了可靠增益，论文也没有做 text sink 的消融。</p><p>反例实验设计：其一，<strong>统一评测协议</strong>——让 AlayaRenderer-Flash 也按 25 帧独立窗口渲染并重新评分，或让 DiffusionRenderer 在完整 150 帧上做窗口拼接（不利协议）后重新评分，看两者的质量差距如何变化。其二，<strong>text sink 消融</strong>——去掉每层 self-attention 的持久 prompt KV，只保留标准 cross-attention，在 637 帧 8 次切换的长 rollout 上测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 随 chunk 索引的衰减曲线。如果两条曲线重合，说明 text sink 是不必要的复杂度。其三，<strong>历史压缩层级消融</strong>——把三级压缩换成单级（只保最近若干 chunk）与两级，看 Boundary SSIM 与长 rollout 外观漂移如何变化，以及全局外观锚点单独去掉的影响。论文报告了 codec、步数、自回归三个大模块的贡献，但自回归模块内部的三个设计（三级压缩、外观锚点、text sink）没有任何一个被单独验证。</p><p>另一类可预测失效场景是<strong>域迁移</strong>。所有主结果都在《黑神话：悟空》上，SuperTuxKart 部署前需要重新采数据微调。这意味着当前系统更像&quot;每个游戏训一个渲染器&quot;，而不是通用的 G-buffer 着色器。可以设计一个零样本迁移测试：在《黑神话：悟空》上训好的模型直接吃 SuperTuxKart 的 G-buffer（不微调），报告 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span><span class="mord text mtight"><span class="mord mtight">-</span></span><span class="mord mathrm mtight">I</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与几何一致性。若退化严重，则&quot;引擎 + 生成渲染器&quot;范式的实际部署成本要按每游戏计。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>本文把 G-buffer 当成一个<strong>固定的、由引擎决定的</strong>接口：五路缓冲，全部以同样的分辨率和频率导出，每 chunk 编码一次。这个接口是延迟渲染的历史产物，不是为生成模型设计的。而生成渲染器的信息需求与传统着色器完全不同——传统着色器需要逐像素的精确材质参数，生成模型需要的是足以消除外观歧义的<strong>最小充分统计量</strong>。</p><p><strong>驱动局限</strong>：五路缓冲既冗余又不足。冗余在于 albedo 与 roughness 在大片同材质区域几乎是常数，却每帧全分辨率编码一次（这正是编码成为瓶颈、需要 tiny encoder 抢救的原因）；不足在于 §9 指出的光源、透明、体积效果完全缺席，而这些恰恰是 prompt 控制最想改的维度。</p><p><strong>可借鉴的相邻领域</strong>：神经压缩里的<strong>率失真优化</strong>，以及主动感知里的<strong>信息增益驱动的传感器调度</strong>。前者提供&quot;在给定比特预算下保留什么&quot;的框架，后者提供&quot;何时该重新测量&quot;的判据。两者结合起来正好回答&quot;引擎每帧该导出什么、导出多少&quot;。</p><p><strong>新的 framing</strong>：把 G-buffer 从&quot;固定接口&quot;改成<strong>可学习的、率失真最优的世界状态编码</strong>——让引擎与生成器共同优化导出什么。引擎侧可以导出稀疏的、按需的通道（例如只在材质边界处高分辨率导 albedo，同时把光源列表作为少量结构化 token 导出），生成器侧学一个码率约束下的条件编码。这不是&quot;给现有管线加个压缩模块&quot;，而是把接口本身变成优化变量。</p><p><strong>第一个实验</strong>：不改引擎，先做离线的通道重要性分析。在已训好的模型上，逐通道做条件消融（把 albedo 置零、把 roughness 换成常数、把 depth 降采样 4 倍等），测量每种消融对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">CLIP</span><span class="mord text mtight"><span class="mord mtight">-</span></span><span class="mord mathrm mtight">I</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、重投影几何一致性与 tLPIPS 的影响。同时统计每个通道的实际信息量（例如逐帧熵与帧间互信息）。如果发现某些通道的消融几乎不影响任何指标，而它们占据了显著的编码开销，就直接证明当前接口存在可回收的冗余；再进一步，从引擎里额外导出光源参数作为结构化条件，测量它对&quot;改光照类 prompt&quot;下几何一致性的改善。这两个方向的结果合起来，就能给出一个数据驱动的、面向生成渲染的新接口规范。</p>',64)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
